// Some portions generated by Claude

// A closing settings pane must end on a frame at most 1 px tall (workbench-disclosure-collapse-geometry.spec.js).
// Chromium paints a border wider than 0 and narrower than 1 px as one device pixel, so a pane whose top and bottom
// borders shrink to 0 over the whole collapse is two borders tall in its last frames before it hides. The borders
// must reach 0 while the pane is still open, and an opening pane must mirror that.
const test = require('node:test');
const assert = require('node:assert/strict');

const { createScriptHarness } = require('./script-harness.js');

const PANE_HEIGHT = 120;
const BOX = {
    boxSizing: 'border-box', paddingTop: '12px', paddingBottom: '12px', borderTopWidth: '1px',
    borderBottomWidth: '1px', marginBlockStart: '0px', marginBlockEnd: '0px'
};
const BORDERS = ['borderTopWidth', 'borderBottomWidth'];

const rect = (left, top, width, height) => ({ left, top, width, height, right: left + width, bottom: top + height,
    x: left, y: top });

/** Records every animation started on element; finish() runs its onfinish as a browser would. */
function recordMotions(element) {
    const motions = [];
    element.animate = (keyframes, timing) => {
        const motion = {
            keyframes, timing, onfinish: null,
            cancel() {},
            finish() {
                if (this.onfinish) {
                    this.onfinish();
                }
            }
        };
        motions.push(motion);
        return motion;
    };
    return motions;
}

/** A bound pane, 120 px tall when open, with 12 px padding and 1 px top and bottom borders. */
function paneHarness() {
    const harness = createScriptHarness();
    harness.document.documentElement = { clientWidth: 1000 };
    harness.runScript('tools/workbench/src/main/webapp/scripts/template.js');
    const element = (tagName, options, parent) => {
        const created = harness.registerElement(tagName, options || {});
        (parent || harness.document.body).appendChild(created);
        return created;
    };
    const card = element('section', { className: 'workbench-island' });
    card.getBoundingClientRect = () => rect(100, 40, 800, 400);
    Object.assign(card, { clientLeft: 1, clientTop: 1, scrollLeft: 0, scrollTop: 0 });
    const owner = element('div', { className: 'workbench-disclosure' }, card);
    const button = element('button', { id: 'pane-toggle',
        attributes: { 'aria-controls': 'pane-panel', 'aria-expanded': 'false' } }, owner);
    button.getBoundingClientRect = () => rect(700, 100, 120, 36);
    const panel = element('div', { id: 'pane-panel', className: 'workbench-disclosure__panel', hidden: true,
        style: BOX }, owner);
    panel.getBoundingClientRect = () => rect(0, 0, 300, panel.hidden ? 0 : PANE_HEIGHT);
    panel.offsetParent = card;
    const motions = recordMotions(panel);
    harness.workbench.detailDisclosure.bind(button, panel, owner);
    return { button, panel, motions };
}

/** Each keyframe's offset; missing ones are spaced evenly between their neighbours, as Web Animations does. */
function keyframeOffsets(keyframes) {
    const offsets = keyframes.map(frame => (frame.offset === undefined || frame.offset === null) ? null : frame.offset);
    if (offsets[0] === null) {
        offsets[0] = 0;
    }
    if (offsets[offsets.length - 1] === null) {
        offsets[offsets.length - 1] = 1;
    }
    let known = 0;
    for (let index = 1; index < offsets.length; index++) {
        if (offsets[index] === null) {
            continue;
        }
        const step = (offsets[index] - offsets[known]) / (index - known);
        for (let missing = known + 1; missing < index; missing++) {
            offsets[missing] = offsets[known] + step * (missing - known);
        }
        known = index;
    }
    return offsets;
}

/** A property's value in px at progress, interpolated between the keyframes that set it. */
function valueAt(motion, property, progress) {
    const offsets = keyframeOffsets(motion.keyframes);
    const stops = motion.keyframes
        .map((frame, index) => ({ offset: offsets[index], value: frame[property] }))
        .filter(stop => stop.value !== undefined);
    assert.ok(stops.length >= 2, `${property} should be animated`);
    for (let index = 1; index < stops.length; index++) {
        const from = stops[index - 1];
        const to = stops[index];
        if (progress <= to.offset) {
            const span = to.offset - from.offset;
            const fraction = span === 0 ? 1 : Math.max(0, progress - from.offset) / span;
            return parseFloat(from.value) + (parseFloat(to.value) - parseFloat(from.value)) * fraction;
        }
    }
    return parseFloat(stops[stops.length - 1].value);
}

/** A border width as Chromium paints it at a device pixel ratio of 1: above 0 and below 1 px is 1 px. */
function paintedBorder(width) {
    return width <= 0 ? 0 : Math.max(1, Math.floor(width));
}

/** The painted height of a border-box pane at progress: its height, but never less than its padding and borders. */
function paintedHeight(motion, progress) {
    const insets = valueAt(motion, 'paddingTop', progress) + valueAt(motion, 'paddingBottom', progress)
        + BORDERS.reduce((sum, border) => sum + paintedBorder(valueAt(motion, border, progress)), 0);
    return Math.max(valueAt(motion, 'height', progress), insets);
}

function openAndSettle(pane) {
    pane.button.click();
    pane.motions[pane.motions.length - 1].finish();
}

test('a closing pane has no top or bottom border in its last frames, so it ends at most 1 px tall', () => {
    const pane = paneHarness();
    openAndSettle(pane);

    pane.button.click();

    assert.equal(pane.motions.length, 2);
    const closing = pane.motions[1];
    for (const border of BORDERS) {
        assert.equal(valueAt(closing, border, 0), 1, `${border} should start at the open pane's width`);
        for (const progress of [0.95, 0.99, 0.999]) {
            assert.equal(valueAt(closing, border, progress), 0, `${border} at progress ${progress}`);
        }
    }
    assert.ok(paintedHeight(closing, 0.999) <= 1,
        `the last frame should be at most 1 px tall, was ${paintedHeight(closing, 0.999)} px`);
    assert.equal(valueAt(closing, 'height', 0.5), PANE_HEIGHT / 2,
        'the height should still shrink evenly over the whole collapse');
});

test('an opening pane gains its borders only after it has grown, mirroring the collapse', () => {
    const pane = paneHarness();

    pane.button.click();
    const opening = pane.motions[0];
    opening.finish();
    pane.button.click();
    const closing = pane.motions[1];

    for (const border of BORDERS) {
        for (const progress of [0.001, 0.05]) {
            assert.equal(valueAt(opening, border, progress), 0, `${border} at progress ${progress}`);
        }
        assert.equal(valueAt(opening, border, 1), 1, `${border} should end at the open pane's width`);
        for (const progress of [0, 0.05, 0.1, 0.3, 0.5, 0.9, 0.95, 1]) {
            assert.ok(Math.abs(valueAt(opening, border, progress) - valueAt(closing, border, 1 - progress)) < 1e-9,
                `${border} at opening progress ${progress} should match the collapse at ${1 - progress}`);
        }
    }
    assert.ok(paintedHeight(opening, 0.001) <= 1,
        `the first frame should be at most 1 px tall, was ${paintedHeight(opening, 0.001)} px`);
});

test('reversing a collapse that still shows its borders keeps them while the pane reopens', () => {
    const pane = paneHarness();
    openAndSettle(pane);
    pane.button.click();

    pane.button.click();

    assert.equal(pane.motions.length, 3);
    const reopening = pane.motions[2];
    for (const border of BORDERS) {
        for (const progress of [0, 0.05, 0.5, 1]) {
            assert.equal(valueAt(reopening, border, progress), 1, `${border} at progress ${progress}`);
        }
    }
});

test('an expanding row gains its borders only after it has grown, like a pane', () => {
    const harness = createScriptHarness();
    harness.runScript('tools/workbench/src/main/webapp/scripts/template.js');
    const row = harness.registerElement('div', { style: Object.assign({ display: 'none' }, BOX) });
    harness.document.body.appendChild(row);
    row.getBoundingClientRect = () => rect(0, 0, 300, row.style.display === 'none' ? 0 : PANE_HEIGHT);
    const motions = recordMotions(row);

    harness.workbench.setElementExpanded(row, true);

    assert.equal(motions.length, 1);
    for (const border of BORDERS) {
        assert.equal(valueAt(motions[0], border, 0.05), 0, `${border} at progress 0.05`);
        assert.equal(valueAt(motions[0], border, 1), 1, `${border} should end at the row's width`);
    }
    assert.equal(valueAt(motions[0], 'opacity', 1), 1, 'the row should still fade in');
});
